reset role;
insert into ezyvet_import_snapshots(id,source_origin,source_site_uid,resource,external_id,payload,payload_hash,first_seen_by) select id,'https://api.trial.ezyvet.com','clinical-test-site','animal',case when k='snapshot' then '77' else '88' end,jsonb_build_object('id',case when k='snapshot' then 77 else 88 end),k,'db490000-0000-4000-8000-000000000001' from fx where k in ('snapshot','snapshot2');
insert into ezyvet_record_links(id,request_id,request_hash,source_origin,source_site_uid,resource,external_id,snapshot_id,head_version,client_id,pet_id,local_version,action,reason,approved_by)
select id,gen_random_uuid(),k,'https://api.trial.ezyvet.com','clinical-test-site','animal',case when k='mapping' then '77' else '88' end,(select id from fx where k=case when m.k='mapping' then 'snapshot' else 'snapshot2' end),1,(select id from fx where k='client'),(select id from fx where k='pet'),1,'link','Synthetic approved mapping','db490000-0000-4000-8000-000000000001' from fx m where k in ('mapping','mapping2');
insert into data values('items','[{"external_id":"101","payload":{"id":101,"animal_id":77,"comments":"<script>outside prose</script>","vet_id":"outside-user","history_system":"opaque"}}]');
insert into fx select k,gen_random_uuid() from unnest(array['source-approval','extraction','linked','tombstone','second-extraction','later-source','discrepancy','release']) k;
set local role service_role;
insert into data select 'run',claim_ezyvet_clinical_import((select id from fx where k='run'),'db490000-0000-4000-8000-000000000001','clinical-test-site','history','https://api.trial.ezyvet.com',(select id from fx where k='mapping'));
select stage_ezyvet_import_page((select id from fx where k='run'),'db490000-0000-4000-8000-000000000001',(select (v->>'lease_id')::uuid from data where k='run'),1,true,(select v from data where k='items'));
set local role authenticated;select set_config('request.jwt.claims','{"sub":"db490000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into data select 'candidate',list_ezyvet_clinical_candidates((select id from fx where k='mapping'),'history')#>'{candidates,0}';
insert into data select 'source-payload',jsonb_build_object('animal_link_id',(select id from fx where k='mapping'),'snapshot_id',v->'id','payload_hash',v->'payload_hash','observed_head_version',v->'head_version','patient_version',1,'consult_mode','not_referenced','consult_snapshot_id',null,'consult_payload_hash',null,'consult_head_version',null,'reason','PRIVATE administrator source review') from data where k='candidate';
insert into data select 'prepared-source',prepare_ezyvet_history_approval((select id from fx where k='source-approval'),(select id from fx where k='pet'),(select v from data where k='source-payload'));
insert into data select 'source-receipt',approve_ezyvet_history((select id from fx where k='source-approval'),(select id from fx where k='pet'),(select v#>>'{request,request_hash}' from data where k='prepared-source'),true);
set local role authenticated;select set_config('request.jwt.claims','{"sub":"db490000-0000-4000-8000-000000000002","role":"authenticated"}',true);
insert into data select 'extraction-payload',jsonb_build_object('sources',jsonb_build_array(jsonb_build_object('id',v#>'{receipt,id}','version_hash',v#>'{receipt,version_hash}')),'patient_version',1,'action','create','problem_id',null,'problem_version',null,'fields',jsonb_build_object('title','Reviewed vaccine reaction','notes','DVM-authored reviewed finding','onset_date',null,'status','active','importance','high'),'duplicate_decision','distinct_finding','reason','PRIVATE DVM duplicate review') from data where k='source-receipt';
insert into data select 'prepared-extraction',prepare_ezyvet_problem_extraction((select id from fx where k='extraction'),(select id from fx where k='pet'),(select v from data where k='extraction-payload'));
insert into data select 'extraction-receipt',approve_ezyvet_problem_extraction((select id from fx where k='extraction'),(select id from fx where k='pet'),(select v#>>'{request,request_hash}' from data where k='prepared-extraction'),true);
insert into fx select 'problem',(v#>>'{receipt,problem_id}')::uuid from data where k='extraction-receipt';

reset role;
insert into ezyvet_identity_heads(source_origin,source_site_uid,resource,external_id,snapshot_id,version)
select source_origin,source_site_uid,resource,external_id,id,1 from ezyvet_import_snapshots where id=(select id from fx where k='snapshot');
insert into fx select k,gen_random_uuid() from unnest(array['migration','scope','binding','approval2']) k;
set local role authenticated;select set_config('request.jwt.claims','{"sub":"db490000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select prepare_ezyvet_migration_run((select id from fx where k='migration'),'https://api.trial.ezyvet.com','clinical-test-site',jsonb_build_array(jsonb_build_object('id',(select id from fx where k='scope'),'mapping_id',(select id from fx where k='mapping'),'resource','history','parent_type','animal','parent_snapshot_id',(select id from fx where k='snapshot'),'parent_head_version',1,'disposition','required','reason','Synthetic history coverage')));
select bind_ezyvet_migration_child((select id from fx where k='binding'),(select id from fx where k='scope'),(select id from fx where k='run'),'Synthetic history run');
insert into data select 'item',list_ezyvet_migration_items((select id from fx where k='binding'))#>'{items,0}';
create function pg_temp.receipts(bef integer default null,lim integer default 20) returns jsonb language sql as $$
select list_ezyvet_migration_history_evidence((select id from fx where k='binding'),1,(v->>'snapshot_id')::uuid,v->>'evidence_hash',bef,lim) from data where k='item';$$;
insert into data select 'first',pg_temp.receipts();
select is((select v#>>'{approvals,0,relationship}' from data where k='first'),'exact_source_version','Approval matches server-verified source evidence hash');
select is((select v#>>'{approvals,0,source_current}' from data where k='first'),'true','Initial reviewed source context is current');
select is((select v#>>'{approvals,0,extraction_receipts}' from data where k='first'),'1','DVM extraction by different actor is visible without exposing pending requests');
select is((select v#>>'{approvals,0,locally_edited_receipts}' from data where k='first'),'0','Unedited local finding is separate from source approval');
select ok(not (select v::text from data where k='first') ~ 'PRIVATE|outside prose|problem_fields|request_hash','Projection omits prose, reasons and request payloads');
select is(pg_temp.receipts()->>'complete_coverage_verified','false','Review receipts never imply accepted coverage');
select is(pg_temp.receipts()->>'discrepancies_assessed','false','Discrepancy assessment remains explicit');
select throws_ok($$select list_ezyvet_migration_history_evidence((select id from fx where k='binding'),1,(v->>'snapshot_id')::uuid,repeat('a',64)) from data where k='item'$$,'42501','Exact owned history observation required','Substituted hash denied');
select throws_ok($$select list_ezyvet_migration_history_evidence((select id from fx where k='binding'),2,(v->>'snapshot_id')::uuid,v->>'evidence_hash') from data where k='item'$$,'42501','Exact owned history observation required','Substituted page denied');
select throws_ok($$select pg_temp.receipts(null,101)$$,'23514','Invalid history evidence identity or cursor','Unbounded page denied');
insert into data select 'prepared2',prepare_ezyvet_history_approval((select id from fx where k='approval2'),(select id from fx where k='pet'),(select v from data where k='source-payload'));
select approve_ezyvet_history((select id from fx where k='approval2'),(select id from fx where k='pet'),(select v#>>'{request,request_hash}' from data where k='prepared2'),true);
select is(pg_temp.receipts(null,1)#>>'{approvals,0,version}','2','Latest correction appears first');
select is(pg_temp.receipts(null,1)->>'has_more','true','Sentinel provides bounded version history');
select is(pg_temp.receipts(null,1)->>'next_before_version','2','Cursor is last selected version');
select is(pg_temp.receipts(2,1)#>>'{approvals,0,superseded}','true','Prior approval remains visible as superseded');
select is(pg_temp.receipts(2,1)->>'has_more','false','Last page is terminal');
reset role;
insert into fx select k,gen_random_uuid() from unnest(array['changed-run','approval3']) k;
update ezyvet_import_runs set retry_after=null where source_site_uid='clinical-test-site' and resource='history';
insert into data select 'changed-run',claim_ezyvet_clinical_import((select id from fx where k='changed-run'),'db490000-0000-4000-8000-000000000001','clinical-test-site','history','https://api.trial.ezyvet.com',(select id from fx where k='mapping'));
select stage_ezyvet_import_page((select id from fx where k='changed-run'),'db490000-0000-4000-8000-000000000001',(select(v->>'lease_id')::uuid from data where k='changed-run'),1,true,'[{"external_id":"101","payload":{"id":101,"animal_id":77,"comments":"Changed source prose"}}]');
set local role authenticated;
insert into data select 'changed-payload',old.v||jsonb_build_object('snapshot_id',c->'id','payload_hash',c->'payload_hash','observed_head_version',c->'head_version') from data old cross join lateral (select c from jsonb_array_elements(list_ezyvet_clinical_candidates((select id from fx where k='mapping'),'history')->'candidates') c where c->>'external_id'='101' and c->>'is_current'='true') candidate where old.k='source-payload';
insert into data select 'prepared3',prepare_ezyvet_history_approval((select id from fx where k='approval3'),(select id from fx where k='pet'),(select v from data where k='changed-payload'));
select approve_ezyvet_history((select id from fx where k='approval3'),(select id from fx where k='pet'),(select v#>>'{request,request_hash}' from data where k='prepared3'),true);
select is(pg_temp.receipts()#>>'{approvals,0,relationship}','different_source_version','New source approval remains distinguishable from bound observation');
select is(pg_temp.receipts()#>>'{approvals,0,source_current}','true','Approval on changed source is independently current');
select is(pg_temp.receipts()#>>'{approvals,0,extraction_receipts}','0','Old extraction is not credited to a new approved version');
reset role;
-- Restore the original payload at a newer head to model A to B to A.
update ezyvet_identity_heads set snapshot_id=(select(v->>'snapshot_id')::uuid from data where k='item') where resource='history' and source_site_uid='clinical-test-site';
update patient_problems set version=version+1,notes='Later local clinician edit' where id=(select id from fx where k='problem');
update ezyvet_identity_heads set version=version+2 where resource='history' and source_site_uid='clinical-test-site';
set local role authenticated;
select is(pg_temp.receipts(2,1)#>>'{approvals,0,locally_edited_receipts}','1','Local edit is retained and reported');
select is(pg_temp.receipts(2,1)#>>'{approvals,0,source_current}','false','A to B to A invalidates currentness despite same payload');
select is(pg_temp.receipts(2,1)#>>'{approvals,0,relationship}','exact_source_version','Source drift does not rewrite the old observation receipt');
select is((select notes from patient_problems where id=(select id from fx where k='problem')),'Later local clinician edit','Evidence reads preserve local chart fields');
select set_config('request.jwt.claims','{"sub":"db490000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select pg_temp.receipts()$$,'42501','Active administrator required','DVM-only actor cannot read migration receipts');
reset role;insert into user_roles(user_id,role) values('db490000-0000-4000-8000-000000000002','ADMIN');set local role authenticated;
select throws_ok($$select pg_temp.receipts()$$,'42501','Exact owned history observation required','Different administrator cannot read owned observation');
reset role;
update profiles set is_active=false where id='db490000-0000-4000-8000-000000000001';
set local role authenticated;select set_config('request.jwt.claims','{"sub":"db490000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select pg_temp.receipts()$$,'42501','Active administrator required','Inactive owner denied');
reset role;
select ok(not has_function_privilege('anon','public.list_ezyvet_migration_history_evidence(uuid,integer,uuid,text,integer,integer)','execute'),'Anonymous read denied');
select ok(not has_function_privilege('service_role','public.list_ezyvet_migration_history_evidence(uuid,integer,uuid,text,integer,integer)','execute'),'Worker read denied');

reset role;select set_config('request.jwt.claims','{"sub":"db490000-0000-4000-8000-000000000002","role":"authenticated"}',true);
update profiles set is_active=true where id='db490000-0000-4000-8000-000000000001';
select set_config('request.jwt.claims','{"sub":"db490000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is((select count(distinct native_id) from ezyvet_migration_terminal_native_outcomes((select id from fx where k='migration')) where native_kind='problem'),1::bigint,'Historical extraction produces one distinct native problem');
select ok(exists(select 1 from ezyvet_migration_terminal_native_outcomes((select id from fx where k='migration')) where native_id=(select id from fx where k='problem') and provenance_id=(select id from fx where k='extraction') and local_changed),'Native problem retains exact extraction provenance and later edits');
select ok(not has_function_privilege('authenticated','public.ezyvet_migration_terminal_native_outcomes(uuid)','execute'),'Native outcome projection is not publicly exposed');
select is(ezyvet_migration_outcome_totals((select id from fx where k='migration'))#>>'{native_outcomes,problem,records}','1','Summary counts distinct native problems');
select is(ezyvet_migration_outcome_totals((select id from fx where k='migration'))#>>'{native_outcomes,problem,locally_changed_records}','1','Summary retains later local edits');
select is(ezyvet_migration_outcome_totals((select id from fx where k='migration'))#>>'{receipts,imported_history,versions}','3','Summary retains immutable history approval versions');
select is(ezyvet_migration_outcome_totals((select id from fx where k='migration'))->>'standalone_consult_approval','not_applicable','No standalone consult approval fabricated');
select is(ezyvet_migration_outcome_totals(gen_random_uuid()),null::jsonb,'Unknown manifest does not become empty success');
select ok(not has_function_privilege('authenticated','public.ezyvet_migration_outcome_totals(uuid)','execute'),'Outcome aggregation stays private before complete summary acceptance');
insert into fx values('preparation',gen_random_uuid());
select prepare_ezyvet_migration_projection((select id from fx where k='preparation'),(select id from fx where k='migration'));
select is(read_ezyvet_migration_dependency_state((select id from fx where k='preparation'))->>'dependencies_unchanged','true','Preparation excludes earlier own-transaction dependency writes');
select is(read_ezyvet_migration_dependency_state((select id from fx where k='preparation'))->>'journal_coverage_valid','true','Installed journal inventory is intact');
savepoint disabled_journal;
alter table patient_problems disable trigger migration_dependency_change;
select is(read_ezyvet_migration_dependency_state((select id from fx where k='preparation'))->>'dependencies_unchanged','false','Disabled trigger cannot imply unchanged dependencies');
select is(read_ezyvet_migration_dependency_state((select id from fx where k='preparation'))->'uncovered_tables','["patient_problems"]'::jsonb,'Missing coverage identifies table');
select throws_ok($$select assert_ezyvet_migration_dependencies((select id from fx where k='preparation'))$$,'55000','Dependency journal coverage incomplete','Coverage failure has repair-specific error');
rollback to savepoint disabled_journal;
savepoint new_dependency;
create table public.ezyvet_future_dependency(id uuid primary key);
select is(read_ezyvet_migration_dependency_state((select id from fx where k='preparation'))->>'journal_coverage_valid','false','New operational table requires journal registration');
select throws_ok($$select prepare_ezyvet_migration_source_chunk((select id from fx where k='preparation'),(select id from fx where k='binding'),1)$$,'55000','Dependency journal coverage incomplete','Uncovered table blocks new source capture');
rollback to savepoint new_dependency;
select is(read_ezyvet_migration_dependency_state((select id from fx where k='preparation'))->>'dependencies_unchanged','true','Rolling back schema test restores intact baseline');
select is(read_ezyvet_migration_report_progress((select id from fx where k='preparation'))->>'missing_source_chunks','1','Report progress begins with missing planned source chunk');
insert into fx values('attempt-page',gen_random_uuid());
insert into data select 'attempt-page',prepare_ezyvet_migration_attempt_page((select id from fx where k='attempt-page'),(select id from fx where k='preparation'),(select id from fx where k='binding'),null,1);
select is((select v->'evidence' from data where k='attempt-page'),list_ezyvet_migration_attempt_events((select id from fx where k='binding'),null,1),'Saved attempt page matches canonical bounded history before source chunks exist');
select is(prepare_ezyvet_migration_attempt_page((select id from fx where k='attempt-page'),(select id from fx where k='preparation'),(select id from fx where k='binding'),null,1),(select v from data where k='attempt-page'),'Attempt page retry recovers exact evidence');
select throws_ok($$select prepare_ezyvet_migration_attempt_page(gen_random_uuid(),(select id from fx where k='preparation'),(select id from fx where k='binding'),null,1)$$,'40001','Attempt history predecessor changed','Parallel root cannot replace selected history chain');
do $$declare tail jsonb;begin
 select v into tail from data where k='attempt-page';
 while (tail->>'has_more')::boolean loop
  tail:=prepare_ezyvet_migration_attempt_page(gen_random_uuid(),(select id from fx where k='preparation'),(select id from fx where k='binding'),(tail->>'id')::uuid,1);
 end loop;
 insert into data values('attempt-tail',tail);
end $$;
select is((select sum(jsonb_array_length(evidence->'events')) from ezyvet_migration_attempt_pages where preparation_id=(select id from fx where k='preparation')),(select count(*) from ezyvet_migration_attempt_events where child_run_id=(select (v->>'child_run_id')::uuid from data where k='attempt-tail')),'Full saved attempt chain retains every event');
select throws_ok($$select prepare_ezyvet_migration_attempt_page(gen_random_uuid(),(select id from fx where k='preparation'),(select id from fx where k='binding'),(select (v->>'id')::uuid from data where k='attempt-tail'),1)$$,'23514','Attempt history already ended','Cannot append beyond terminal attempt page');
select ok(not has_table_privilege('authenticated','public.ezyvet_migration_attempt_pages','select'),'Saved attempt pages remain private');
insert into data select 'source-chunk',prepare_ezyvet_migration_source_chunk((select id from fx where k='preparation'),(select id from fx where k='binding'),1);
create function pg_temp.prepared_history(bef integer default null,lim integer default 1) returns jsonb language sql as $$
 select read_ezyvet_migration_prepared_history_evidence((select id from fx where k='preparation'),(select id from fx where k='binding'),1,1,bef,lim);$$;
select is(pg_temp.prepared_history()->'approvals',pg_temp.receipts(null,1)->'approvals','Saved observation reuses canonical history approval interpretation');
select is(pg_temp.prepared_history()#>>'{approvals,0,version}','3','Prepared history reader starts at latest revision');
select is(pg_temp.prepared_history()->>'has_more','true','Approval revisions remain bounded with a sentinel');
select is(pg_temp.prepared_history(3)#>>'{approvals,0,version}','2','Prepared history cursor recovers earlier revision');
select is(pg_temp.prepared_history(2)#>>'{approvals,0,superseded}','true','Prepared history retains superseded approvals');
select is(pg_temp.prepared_history(2)#>>'{approvals,0,locally_edited_receipts}','1','Saved source retains canonical later local-edit evidence');
select is(pg_temp.prepared_history()->>'source_chunk_hash',(select v->>'evidence_hash' from data where k='source-chunk'),'Approval response binds exact saved source chunk');
select is(pg_temp.prepared_history()->>'dependency_consistency_verified','false','Paged approval read cannot claim cross-chunk consistency');
select throws_ok($$select pg_temp.prepared_history(null,101)$$,'23514','Invalid prepared history cursor','Prepared approval read refuses unbounded page');
select throws_ok($$select read_ezyvet_migration_prepared_history_evidence((select id from fx where k='preparation'),(select id from fx where k='binding'),1,2)$$,'23514','Saved history observation required','Missing saved observation rejected');
select ok(not has_function_privilege('authenticated','public.read_ezyvet_migration_prepared_history_evidence(uuid,uuid,integer,integer,integer,integer)','execute'),'Prepared history adapter remains internal');
select is(read_ezyvet_migration_prepared_versioned_evidence((select id from fx where k='preparation'),(select id from fx where k='binding'),1,1,null,1)->'approvals',pg_temp.prepared_history()->'approvals','Shared versioned adapter preserves history-specific interpretation');
select ok(not has_function_privilege('authenticated','public.read_ezyvet_migration_prepared_versioned_evidence(uuid,uuid,integer,integer,integer,integer)','execute'),'Shared versioned adapter remains private');


select throws_ok($$select read_ezyvet_migration_prepared_identity_evidence((select id from fx where k='preparation'),(select id from fx where k='binding'),1,1)$$,'23514','Saved identity observation required','Identity reader rejects history source');
select throws_ok($$select read_ezyvet_migration_prepared_timed_evidence((select id from fx where k='preparation'),(select id from fx where k='binding'),1,1)$$,'23514','Saved timed observation required','Timed reader rejects history source');
select throws_ok($$select read_ezyvet_migration_prepared_timed_evidence(null,null,1,1,now(),null)$$,'23514','Invalid prepared timed cursor','Incomplete time cursor rejected');
select throws_ok($$select read_ezyvet_migration_prepared_timed_evidence(null,null,1,1,'infinity',gen_random_uuid())$$,'23514','Invalid prepared timed cursor','Nonfinite time cursor rejected');
select throws_ok($$select read_ezyvet_migration_prepared_identity_evidence(null,null,1,0)$$,'23514','Invalid prepared identity observation','Invalid identity ordinal rejected');
select ok(not has_function_privilege('authenticated','public.read_ezyvet_migration_prepared_identity_evidence(uuid,uuid,integer,integer)','execute'),'Prepared identity stays private');
select ok(not has_function_privilege('authenticated','public.read_ezyvet_migration_prepared_timed_evidence(uuid,uuid,integer,integer,timestamptz,uuid,integer)','execute'),'Prepared timed reader stays private');
select throws_ok($$select read_ezyvet_migration_prepared_timed_evidence(gen_random_uuid(),gen_random_uuid(),1,1)$$,'42501','Owned source chunk required','Unknown timed chunk rejected');
create function pg_temp.prepared_native(approval_key text default 'source-approval',bef uuid default null,lim integer default 1) returns jsonb language sql as $$
 select read_ezyvet_migration_prepared_native_evidence((select id from fx where k='preparation'),(select id from fx where k='binding'),1,1,(select id from fx where k=approval_key),bef,lim);$$;
select is(pg_temp.prepared_native()#>>'{outcomes,0,provenance_id}',(select id::text from fx where k='extraction'),'Saved native provenance identifies exact DVM extraction');
select is(pg_temp.prepared_native()#>>'{outcomes,0,native_id}',(select id::text from fx where k='problem'),'Saved native provenance identifies local problem');
select is(pg_temp.prepared_native()#>>'{outcomes,0,local_changed}','true','Later local edits stay visible');
select is(pg_temp.prepared_native()#>>'{outcomes,0,action}','create','Native creation remains distinct from source approval');
select is(pg_temp.prepared_native('approval2')->'outcomes','[]'::jsonb,'Later same-source approval does not inherit earlier extraction');
select is(pg_temp.prepared_native('approval3')->'outcomes','[]'::jsonb,'Different source revision does not inherit earlier extraction');
