insert into fx values('saved-review',gen_random_uuid());
create function pg_temp.save_review(kind text default 'native') returns jsonb language sql as $$
 select prepare_ezyvet_migration_review_page((select id from fx where k='saved-review'),(select id from fx where k='preparation'),(select id from fx where k='binding'),1,1,kind,null,null,null,case when kind='native' then (select id from fx where k='source-approval') else null end,1);$$;
